use darling::{FromDeriveInput, FromVariant, ast::Fields};
use proc_macro2::{Span, TokenStream};
use quote::quote;
use syn::Ident;

/// Name of the module generated by the [`CanEncode`] macro which contains the
/// CAN encode implementation of the message enum
pub const CAN_ENCODE_MESSAGE_META_TYPES_IDENT: &str = "__message_meta_can_encode";

// The [`darling::FromVariant`] macro seems to have needless continues
#[allow(clippy::needless_continue)]
#[derive(FromVariant)]
pub struct CanEncodeVariant {
    ident: Ident,
    fields: Fields<syn::Field>,
}

#[derive(FromDeriveInput)]
#[darling(attributes(can), supports(enum_any))]
pub struct CanEncode {
    #[darling(default)]
    /// Boolean whether the enum should be sparsely decodable
    pub sparse: bool,
    #[darling(default)]
    /// Boolean whether all enum variants need to be newtypes and have
    /// [`can_hal::Encode`] implemented
    pub dispatch: bool,

    pub ident: Ident,
    pub data: darling::ast::Data<CanEncodeVariant, ()>,
}

pub fn handle(can_encode: CanEncode) -> TokenStream {
    let variants = can_encode.data.take_enum().unwrap_or_default();

    let impl_mod_ident = Ident::new(CAN_ENCODE_MESSAGE_META_TYPES_IDENT, Span::call_site());

    quote! {
        pub mod #impl_mod_ident {}
    }
}
